import { useState } from 'react';

export type Props = {
  initialName: string;
  onSubmit: (name: string) => void;
};

const theme = {
  colors: { background: '#f2f6fc', text: '#1d3150' },
  spacing: { panel: 16, gap: 8 },
  typography: { fontFamily: 'system-ui, sans-serif', fontSize: 14 },
};

export function Component({ initialName, onSubmit }: Props) {
  const [name, setName] = useState(initialName);
  const [reviewing, setReviewing] = useState(false);
  const [hasError, setHasError] = useState(false);

  return (
    <form
      aria-label="Name wizard"
      data-testid="panel"
      style={{
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: theme.colors.background,
        color: theme.colors.text,
        padding: theme.spacing.panel,
        gap: theme.spacing.gap,
        fontFamily: theme.typography.fontFamily,
        fontSize: theme.typography.fontSize,
      }}
      onSubmit={(event) => {
        event.preventDefault();
        if (reviewing) {
          onSubmit(name);
          return;
        }

        const cleanedName = name.trim();
        if (cleanedName === '') {
          setHasError(true);
          return;
        }

        setName(cleanedName);
        setHasError(false);
        setReviewing(true);
      }}
    >
      {reviewing ? (
        <>
          <output aria-label="Review name">{name}</output>
          <button type="button" onClick={() => setReviewing(false)}>Back</button>
          <button type="submit">Submit</button>
        </>
      ) : (
        <>
          <label>
            Name
            <input
              type="text"
              value={name}
              aria-invalid={hasError}
              onChange={(event) => setName(event.currentTarget.value)}
            />
          </label>
          <button type="submit">Next</button>
          {hasError && <p role="alert">Name required</p>}
        </>
      )}
    </form>
  );
}
